// Prepares the data points for MQTT: four messages with the topics
// viessmann/sensors, /boiler, /dhw and /circuit.
// Bereitet die Datenpunkte für MQTT auf (vier Nachrichten, Topics siehe oben).
//
// Accepts the output of the Viessmann read node (object per data point) and
// also the raw form { data: [...] } for test injects.

const src = msg.payload;
let map = {};
if (src && Array.isArray(src.data)) {
    for (const f of src.data) map[f.feature] = f;
} else if (src && typeof src === 'object') {
    map = src;
}

// Returns the value of a property, or null if the device does not deliver it.
// "features" may be a list: the first data point with a value wins
// (new name before deprecated name).
function get(features, prop) {
    for (const name of [].concat(features)) {
        const f = map[name];
        if (!f || f.isEnabled === false || !f.properties) continue;
        const p = f.properties[prop];
        if (p && p.value !== undefined && p.value !== null && p.value !== '') return p.value;
    }
    return null;
}

// [field name, data point(s), property] – one line per value, extend as you like.
// [Feldname, Datenpunkt(e), Eigenschaft] – eine Zeile je Wert, beliebig erweiterbar.
const groups = [
    { topic: 'viessmann/sensors', fields: [
        ['outsideTemperature', 'heating.sensors.temperature.outside', 'value']
    ]},
    { topic: 'viessmann/boiler', fields: [
        ['boilerTemperature', 'heating.boiler.sensors.temperature.main', 'value'],
        ['serial', ['device.serial', 'heating.boiler.serial'], 'value'],
        ['commonSupplyTemperature', 'heating.boiler.sensors.temperature.commonSupply', 'value'],
        ['targetTemperature', 'heating.boiler.temperature', 'value'],
        ['burnerModulation', 'heating.burners.0.modulation', 'value'],
        ['burnerHours', 'heating.burners.0.statistics', 'hours'],
        ['burnerStarts', 'heating.burners.0.statistics', 'starts']
    ]},
    { topic: 'viessmann/dhw', fields: [
        ['dhwTemperature', ['heating.dhw.sensors.temperature.dhwCylinder', 'heating.dhw.sensors.temperature.hotWaterStorage'], 'value'],
        ['dhwTarget', 'heating.dhw.temperature.main', 'value'],
        ['chargingPump', 'heating.dhw.pumps.primary', 'status'],
        ['circulationPump', 'heating.dhw.pumps.circulation', 'status'],
        ['charging', 'heating.dhw.charging', 'active']
    ]},
    { topic: 'viessmann/circuit', fields: [
        ['supplyTemperature', 'heating.circuits.0.sensors.temperature.supply', 'value'],
        ['circuitPump', 'heating.circuits.0.circulation.pump', 'status'],
        ['activeMode', 'heating.circuits.0.operating.modes.active', 'value'],
        ['activeProgram', 'heating.circuits.0.operating.programs.active', 'value'],
        ['comfortActive', 'heating.circuits.0.operating.programs.comfort', 'active'],
        ['comfortTemperature', 'heating.circuits.0.operating.programs.comfort', 'temperature'],
        ['ecoActive', 'heating.circuits.0.operating.programs.eco', 'active'],
        ['curveShift', 'heating.circuits.0.heating.curve', 'shift'],
        ['curveSlope', 'heating.circuits.0.heating.curve', 'slope']
    ]}
];

const out = [];
for (const g of groups) {
    const values = {};
    for (const [key, feature, prop] of g.fields) values[key] = get(feature, prop);
    values.time = new Date().toISOString();
    out.push({ topic: g.topic, payload: values });
}

node.status({ fill: 'green', shape: 'dot',
    text: new Date().toLocaleTimeString() + ': ' + get('heating.sensors.temperature.outside', 'value') + ' °C' });
return [out];
